def get_user_info(data, user_id):
    for user in data:
        if user['id'] == user_id:
            return {'name': user.get('name'), 'email': user.get('email')}
    return None

import copy

def duplicate_list(lst):
    return [copy.deepcopy(lst), copy.deepcopy(lst)]

def safe_divide(a, b):
    if not isinstance(a, (int, float)) or not isinstance(b, (int, float)):
        return None
    if b == 0:
        return None
    result = a / b
    if result != int(result):
        return None
    return int(result)
